import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    from scipy import stats as sp_stats

    date_col = 'Wk_End_Dt'
    metrics = ['Net Sales', 'Units', 'COGS']
    seg_cols = ['Dept', 'Region']

    df[date_col] = pd.to_datetime(df[date_col])

    sale_mask = df['row_kind'].isin(['sale', 'return'])
    sales_only = df[df['row_kind'] == 'sale']
    returns_only = df[df['row_kind'].isin(['return', 'refunded'])]
except Exception as e:
    sale_mask = pd.Series([True] * len(df))
    sales_only = df
    returns_only = df[df['row_kind'] == 'return'] if 'row_kind' in df.columns else df.iloc[0:0]

# EDA
try:
    eda = {}
    for col in metrics:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# Correlations
try:
    num_cols = ['Net Sales', 'Units', 'COGS']
    corr_dict = {}
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            pair = df[[c1, c2]].dropna()
            if len(pair) > 1:
                r, _ = sp_stats.pearsonr(pair[c1], pair[c2])
                if abs(r) >= 0.2:
                    corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# Trends - 7d rolling on weekly data
try:
    trends = []
    df_sorted = df.sort_values(date_col)
    for metric in metrics:
        weekly = df_sorted.groupby(date_col)[metric].sum().reset_index()
        weekly['rolling'] = weekly[metric].rolling(7, min_periods=1).mean()
        if len(weekly) >= 2:
            first_val = float(weekly['rolling'].iloc[0])
            last_val = float(weekly['rolling'].iloc[-1])
            if first_val != 0:
                pct = round((last_val - first_val) / abs(first_val) * 100, 2)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            trends.append({
                "column": metric, "period": "7d_rolling",
                "direction": direction, "pct_change": pct, "segment": None
            })
    result['trends'] = trends
except Exception:
    pass

# Segmentation
try:
    segs = []
    for seg in seg_cols:
        top10 = df[seg].value_counts().head(10).index.tolist()
        sub = df[df[seg].isin(top10)]
        for metric in metrics:
            grp = sub.groupby(seg)[metric].sum()
            segs.append({
                "segment_column": seg, "metric_column": metric,
                "aggregation": "sum", "label": None,
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg)[metric].count()
        segs.append({
            "segment_column": seg, "metric_column": "Net Sales",
            "aggregation": "count", "label": None,
            "results": [{"name": str(k), "value": int(v)} for k, v in sub.groupby(seg)['Net Sales'].count().items()]
        })
    # Gross margin ratio by Dept
    sale_ret = df[df['row_kind'].isin(['sale', 'return'])] if 'row_kind' in df.columns else df
    for seg in seg_cols:
        top10 = sale_ret[seg].value_counts().head(10).index.tolist()
        sub = sale_ret[sale_ret[seg].isin(top10)]
        gm = sub.groupby(seg).apply(lambda x: (x['Net Sales'].sum() - x['COGS'].sum()) / x['Net Sales'].sum() if x['Net Sales'].sum() != 0 else 0)
        segs.append({
            "segment_column": seg, "metric_column": "Net Sales",
            "aggregation": "ratio", "label": "gross_margin_pct",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in gm.items()]
        })
    result['segments'] = segs
except Exception:
    pass

# Anomalies
try:
    anomalies = []
    total_cap = 25
    for col in metrics:
        if len(anomalies) >= total_cap:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution."
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_ext) - shift)
            hi_orig = float(np.expm1(hi_ext) - shift)
        else:
            lo_orig = float(lo_ext)
            hi_orig = float(hi_ext)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        for idx in flagged.index:
            if len(anomalies) >= total_cap:
                break
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            lo5 = q1 - 5 * iqr
            hi5 = q3 + 5 * iqr
            lo4 = q1 - 4 * iqr
            hi4 = q3 + 4 * iqr
            if t_val > hi5 or t_val < lo5:
                sev = "critical"
            elif t_val > hi4 or t_val < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {raw_val:.2f} lies outside expected range {exp_range}."
            })
    result['anomalies'] = anomalies
except Exception:
    pass

# Forecasting - simple linear extrapolation on weekly totals
try:
    fp = []
    df_s = df.sort_values(date_col)
    weekly_ns = df_s.groupby(date_col)['Net Sales'].sum().reset_index()
    weekly_ns['t'] = np.arange(len(weekly_ns))
    if len(weekly_ns) >= 4:
        slope, intercept, _, _, _ = sp_stats.linregress(weekly_ns['t'], weekly_ns['Net Sales'])
        last_t = weekly_ns['t'].max()
        last_date = weekly_ns[date_col].max()
        for i in range(1, 5):
            future_date = last_date + pd.Timedelta(weeks=i)
            pred = intercept + slope * (last_t + i)
            fp.append({"period": str(future_date.date()), "value": round(float(pred), 2)})
    result['forecast_points'] = fp
except Exception:
    pass

result['assumptions'] = [
