try:
    anomalies = []
    total_cap = 25
    for col in metrics:
        if len(anomalies) >= total_cap:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution."
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_ext) - shift)
            hi_orig = float(np.expm1(hi_ext) - shift)
        else:
            lo_orig = float(lo_ext)
            hi_orig = float(hi_ext)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        for idx in flagged.index:
            if len(anomalies) >= total_cap:
                break
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            lo5 = q1 - 5 * iqr
            hi5 = q3 + 5 * iqr
            lo4 = q1 - 4 * iqr
            hi4 = q3 + 4 * iqr
            if t_val > hi5 or t_val < lo5:
                sev = "critical"
            elif t_val > hi4 or t_val < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {raw_val:.2f} lies outside expected range {exp_range}."
            })
    result['anomalies'] = anomalies
except Exception:
    pass

# Forecasting - simple linear extrapolation on weekly totals
try:
    fp = []
    df_s = df.sort_values(date_col)
    weekly_ns = df_s.groupby(date_col)['Net Sales'].sum().reset_index()
    weekly_ns['t'] = np.arange(len(weekly_ns))
    if len(weekly_ns) >= 4:
        slope, intercept, _, _, _ = sp_stats.linregress(weekly_ns['t'], weekly_ns['Net Sales'])
        last_t = weekly_ns['t'].max()
        last_date = weekly_ns[date_col].max()
        for i in range(1, 5):
            future_date = last_date + pd.Timedelta(weeks=i)
            pred = intercept + slope * (last_t + i)
            fp.append({"period": str(future_date.date()), "value": round(float(pred), 2)})
    result['forecast_points'] = fp
except Exception:
    pass

